import collections


class VaultKV:
    def __init__(self):
        self._data = {}
        self._locks = set()
        self._transactions = []
        self._reverse = collections.defaultdict(set)

    def put(self, key, value):
        if self._transactions:
            if key in self._locks:
                raise PermissionError("key is locked")
            old_value = self._data.get(key)
            self._data[key] = value
            self._transactions[-1]['_changes'][key] = (old_value, value)
            if old_value is not None:
                self._reverse[old_value].discard(key)
            self._reverse[value].add(key)
        else:
            if key in self._locks:
                raise PermissionError("key is locked")
            old_value = self._data.get(key)
            self._data[key] = value
            if old_value is not None:
                self._reverse[old_value].discard(key)
            self._reverse[value].add(key)

    def get(self, key, default=None):
        return self._data.get(key, default)

    def drop(self, key):
        if self._transactions:
            if key in self._locks:
                raise PermissionError("key is locked")
        if key not in self._data:
            return False
        old_value = self._data[key]
        del self._data[key]
        if self._transactions:
            self._transactions[-1]['_changes'][key] = (old_value, None)
            self._reverse[old_value].discard(key)
        else:
            self._reverse[old_value].discard(key)
        return True

    def incr(self, key, by=1):
        if self._transactions:
            if key in self._locks:
                raise PermissionError("key is locked")
        if key not in self._data:
            old_value = 0
            self._data[key] = 0
            if self._transactions:
                self._transactions[-1]['_changes'][key] = (0, 0)
            else:
                self._reverse[0].add(key)
        else:
            old_value = self._data[key]
            if not isinstance(old_value, int):
                raise TypeError("key holds a string")
        self._data[key] = old_value + by
        if self._transactions:
            self._transactions[-1]['_changes'][key] = (old_value, self._data[key])
        if old_value is not None:
            self._reverse[old_value].discard(key)
        self._reverse[self._data[key]].add(key)
        return self._data[key]

    def holders(self, value):
        return sorted(self._reverse.get(value, set()))

    def size(self):
        return len(self._data)

    def lock(self, key):
        if self._transactions:
            self._transactions[-1]['_lock_changes'][key] = (False, True)
        self._locks.add(key)

    def unlock(self, key):
        if self._transactions:
            self._transactions[-1]['_lock_changes'][key] = (True, False)
        self._locks.discard(key)

    def locked(self, key):
        return key in self._locks

    def begin(self, name=None):
        self._transactions.append({
            '_changes': {},
            '_lock_changes': {},
            '_name': name
        })
        return len(self._transactions)

    def commit(self):
        if not self._transactions:
            raise RuntimeError("no transaction open")
        for key, (old_value, new_value) in self._transactions[-1]['_changes'].items():
            if new_value is None:
                del self._data[key]
                self._reverse[old_value].discard(key)
            else:
                self._data[key] = new_value
                if old_value is not None:
                    self._reverse[old_value].discard(key)
                self._reverse[new_value].add(key)
        for key, (was_locked, is_locked) in self._transactions[-1]['_lock_changes'].items():
            if is_locked:
                self._locks.add(key)
            else:
                self._locks.discard(key)
        self._transactions.pop()
        return len(self._transactions)

    def rollback(self, name=None):
        if not self._transactions:
            raise RuntimeError("no transaction open")
        if name is None:
            target = len(self._transactions) - 1
            self._transactions.pop()
        else:
            target = None
            for i, txn in enumerate(self._transactions):
                if txn['_name'] == name:
                    target = i
            if target is None:
                raise KeyError("no transaction with that name")
            saved_transactions = self._transactions[target:]
            self._transactions = self._transactions[:target]
        for txn in reversed(saved_transactions):
            for key, (old_value, new_value) in txn['_changes'].items():
