def resolve_profiles(text: str) -> dict:
    lines = text.split("\n")
    cleaned = []
    for line in lines:
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        cleaned.append(line)

    headers = {}  # name -> list of parent names
    profile_ops = {}  # name -> list of operations
    current_profile = None

    for line in cleaned:
        if line.startswith("[") and line.endswith("]"):
            name = line[1:-1].strip()
            if not name:
                raise ValueError("Empty name in header")
            if name in headers:
                raise ValueError("Duplicate profile name")
            if "<" in line:
                left, right = line[1:-1].split("<", 1)
                left = left.strip()
                right = right.strip()
                parents = [p.strip() for p in right.split(",")]
                if any not p for p in parents:
                    raise ValueError("Empty parent name")
            else:
                parents = []
            headers[name] = parents
            current_profile = name
        elif current_profile is None:
            raise ValueError("Operation line before first header")
        else:
            op = parse_op(line)
            profile_ops.setdefault(current_profile, []).append(op)

    # Build raw maps with inheritance and operations
    raw_maps = {}

    def build_raw(name):
        if name in raw_maps:
            return raw_maps[name]
        if name not in headers:
            raise ValueError(f"Unknown parent: {name}")
        parents = headers[name]
        result = {}
        for parent in parents:
            parent_raw = build_raw(parent)
            for key, value in parent_raw.items():
                result[key] = value
        for op in profile_ops.get(name, []):
            apply_op(result, op)
        raw_maps[name] = result
        return result

    for name in headers:
        raw_maps[name] = build_raw(name)

    # Resolve interpolation
    resolved = {}
    for name in headers:
        resolved[name] = {}
        for key, value in raw_maps[name].items():
            resolved[name][key] = resolve_value(value, name, resolved[name])

    return resolved


def parse_op(line):
    if line.startswith("!"):
        key = line[1:].strip()
        if not key:
            raise ValueError("Empty key after !")
        return ("delete", key)
    eq_pos = line.find("=")
    if eq_pos == -1:
        raise ValueError("No = in operation line")
    char_before = line[eq_pos - 1]
    if char_before == "+":
        op = "+="
        key = line[:eq_pos - 1].strip()
    elif char_before == "-":
        op = "-="
        key = line[:eq_pos - 1].strip()
    else:
        op = "="
        key = line[:eq_pos].strip()
    if not key:
        raise ValueError("Empty key")
    value = line[eq_pos + 1:].strip()
    return (op, key, value)


def apply_op(result, op):
    if op == "delete":
        if op[1] in result:
            del result[op[1]]
    elif op == "=":
        result[op[1]] = op[2]
    elif op == "+=":
        pieces = [p.strip() for p in op[2].split(",")]
        pieces = [p for p in pieces if p]
        if op[1] not in result:
            result[op[1]] = []
        elif isinstance(result[op[1]], str):
            result[op[1]] = [result[op[1]]]
        result[op[1]].extend(pieces)
    elif op == "-=":
        if op[1] not in result:
            return
        if isinstance(result[op[1]], str):
            raise ValueError("Key holds a string")
        pieces = [p.strip() for p in op[2].split(",")]
        pieces = [p for p in pieces if p]
        result[op[1]] = [p for p in result[op[1]] if p not in pieces]


def resolve_value(value, profile_name, resolved):
    result = ""
    i = 0
    while i < len(value):
        if value[i] == "$":
            if i + 1 < len(value) and value[i + 1] == "$":
                result += "$"
                i += 2
            elif i + 1 < len(value) and value[i + 1] == "{":
                close = value.find("}", i + 2)
                if close == -1:
                    raise ValueError("Unclosed ${")
                key = value[i + 2:close].strip()
                if key not in resolved:
                    raise ValueError(f"Unknown key: {key}")
                val = resolved[key]
                if isinstance(val, list):
                    result += ",".join(val)
                else:
                    result += val
                i = close + 1
            else:
                raise ValueError("Invalid $ reference")
        else:
            result += value[i]
            i += 1
    return result
