```python
def reflow(src: str, width: int) -> str:
    """Parse Lath notation and render it in canonical layout."""

    def parse(text):
        """Parse Lath notation into a list of items."""
        i = 0

        def parse_item():
            nonlocal i
            # Skip whitespace
            while i < len(text) and text[i] in ' \t\n\r':
                i += 1

            if i >= len(text):
                return

            if text[i] == '"':
                # Parse string
                i += 1
                result = ""
                while i < len(text):
                    if text[i] == '\\':
                        i += 2
                        result += text[i-1]
                    elif text[i] == '"':
                        i += 1
                        break
                    else:
                        result += text[i]
                        i += 1
                return result
            elif text[i] == ';':
                # Skip comment
                while i < len(text) and text[i] != '\n':
                    i += 1
                if i < len(text):
                    i += 1
                return
            elif text[i] == '(' or text[i] == '[':
                # Parse list
                open_bracket = text[i]
                i += 1
                items = parse_list_items()
                # Find closing bracket
                depth = 1
                while i < len(text):
                    if text[i] == '(':
                        depth += 1
                    elif text[i] == ')':
                        depth -= 1
                        if depth == 0:
                            break
                    elif text[i] == '[':
                        depth += 1
                    elif text[i] == ']':
                        depth -= 1
                        if depth == 0:
                            break
                    elif text[i] == '"':
                        # Skip string
                        i += 1
                        while i < len(text):
                            if text[i] == '\\':
                                i += 2
                            elif text[i] == '"':
                                i += 1
                                break
                            else:
                                i += 1
                    elif text[i] == ';':
                        # Skip comment
                        while i < len(text) and text[i] != '\n':
                            i += 1
                        if i < len(text):
                            i += 1
                    else:
                        i += 1
                i += 1  # Skip closing bracket
                return [open_bracket, items]
            else:
                # Parse atom
                result = ""
                while i < len(text) and text[i] not in ' \t\n\r' and text[i] not in '()[]"' and text[i] != ';':
                    result += text[i]
                    i += 1
                return result

        def parse_list_items():
            """Parse items inside a list."""
            result = []
            while True:
                # Skip whitespace
                while i < len(text) and text[i] in ' \t\n\r':
                    i += 1
                if i >= len(text):
                    break
                if text[i] == ')' or text[i] == ']':
                    break
                result.append(parse_item())
                # Skip whitespace after item
                while i < len(text) and text[i] in ' \t\n\r':
                    i += 1
            return result

        result = []
        while i < len(text):
            item = parse_item()
            if item is not None:
                result.append(item)
        return result

    items = parse(src)

    def get_flat(item):
        """Get the flat form of an item."""
        if isinstance(item, str):
            return item
        if isinstance(item, list):
            # List: [open_bracket, items]
            open_bracket, items = item
            if len(items) == 0:
                return open_bracket + open_bracket
            return open_bracket + " ".join(get_flat(i) for i in items) + open_bracket
        # Atom
        return item

    def get_trail(item):
        """Get the number of trailing closing brackets."""
        if isinstance(item, str):
            return 0
        if isinstance(item, list):
            # List: [open_bracket, items]
            open_bracket, items = item
            # Each item in the list might have trailing brackets
            # The last item determines the trail
            if len(items) == 0:
                return 0
            return get_trail(items[-1]) + 1
        # Atom
        return 0

    def render(item, col, trail):
        """Render an item starting at column col with trail trailing brackets."""
        flat = get_flat(item)
        flat_len = len(flat)

        if isinstance(item, str):
            return flat
        if isinstance(item, list):
            open_bracket, items = item

            # Check if flat form fits
            if len(items) == 0 or col + flat_len + trail <= width:
                return flat

            # Otherwise, broken
            if open_bracket == '(' and isinstance(items[0], str) and len(items) >= 2:
                # HEAD STYLE
                # First line: ( immediately followed by first item (at col)
                # Other items: new line at col + 2, with trail
                # Last item: new line at col + 2, with trail + 1 (closing bracket follows)
                result = [open_bracket + items[0]]
                for i in range(1, len(items)):
                    result.append(" " * (col + 2) + render(items[i], col + 2, trail))
                result.append(" " * (col + 2) + render(items[-1], col + 2, trail + 1))
                return "\n".join(result)
            else:
                # BLOCK STYLE
                # First item at col + 1, with trail
                # Other items at col + 1, with trail
                # Last item at col + 1, with trail + 1 (closing bracket follows)
                result = [open_bracket + render(items[0], col + 1, trail)]
                for i in range(1, len(items)):
                    result.append(" " * (col + 1) + render(items[i], col + 1, trail))
                result.append(" " * (col + 1) + render(items[-1], col + 1, trail + 1))
                return "\n".join(result)

        # Atom
        return flat

    def render_top_level(item):
        """Render a top-level item."""
        return render(item, 0, 0)

    # Render all top-level items
    result = "\n".join(render_top_level(item) for item in items)
    return result
