import re

def pluck(data, query: str) -> list:
    """Select values from nested data with a small query language."""
    if not query:
        return [data]

    # Regex patterns for each step type (in order of priority)
    patterns = [
        (r'\.([a-zA-Z_][a-zA-Z0-9_]*)', 'key'),
        (r'\["((?:[^"]|\\.)*)"\]', 'key_string'),
        (r'\[((-?\d*)?:(-?\d*)?)\]', 'slice'),
        (r'\[(-?\d+)]', 'index'),
        (r'\[\*\]', 'wildcard'),
        (r'\.\.([a-zA-Z_][a-zA-Z0-9_]*)', 'deep'),
        (r'\[?([a-zA-Z_][a-zA-Z0-9_]*)\s*(==|!=|<|<=|>|>=)\s*((-?\d+)|"((?:[^"]|\\.)*)"\)]', 'filter'),
    ]

    steps = []
    i = 0
    while i < len(query):
        for pattern, step_type in patterns:
            match = re.match(pattern, query[i:])
            if match:
                steps.append((step_type, match.group(1)))
                i += match.end()
                break
        else:
            raise ValueError(f"Unexpected character at position {i}: {query[i]}")

    # Validate string contents
    for step in steps:
        if step[0] == 'key_string':
            validate_string(step[1])

    # Evaluate steps
    nodes = [data]
    for step in steps:
        nodes = evaluate_step(step, nodes)

    return nodes


