            if isinstance(node, dict) and step[1] in node:
                result.append(node[step[1]])
        elif step[0] == 'index':
            # [INT] - list index access
            if isinstance(node, list):
                idx = int(step[1])
                if -len(node) <= idx < len(node):
                    result.append(node[idx])
        elif step[0] == 'slice':
            # [A:B] - list slice
            if isinstance(node, list):
                a = int(step[1][0]) if step[1][0] != '' else None
                b = int(step[1][1]) if step[1][1] != '' else None
                result.extend(node[a:b])
        elif step[0] == 'wildcard':
            # [*] - all elements
            if isinstance(node, list):
                result.extend(node)
            elif isinstance(node, dict):
