def deep_search(node, name):
    """Deep search: visit node itself, then children."""
    result = []

    # Visit the node itself
    if isinstance(node, dict) and name in node:
        result.append(node[name])

    # Visit children (dict values in insertion order, list elements in order)
    if isinstance(node, dict):
        for value in node.values():
            result.extend(deep_search(value, name))
    elif isinstance(node, list):
        for element in node:
            result.extend(deep_search(element, name))

    return result
